1	using System.Security.Claims;
2	using FluentValidation;
3	using Kanban.Api.Auth;
4	using Microsoft.AspNetCore.Authentication;
5	using Kanban.Business.Interfaces;
6	using Kanban.Business.Transforms;
7	using Kanban.Contracts;
8	using Kanban.Domain.Enums;
9	using Microsoft.AspNetCore.Authentication.Cookies;
10	using Microsoft.AspNetCore.Mvc;
11	using Microsoft.Extensions.Logging;
12	using Microsoft.Extensions.Options;
13	using CorsOptions = Kanban.Api.Options.CorsOptions;
14	
15	namespace Kanban.Api.Endpoints;
16	
17	public static class InviteEndpoints
18	{
19	    public static void MapAcceptEndpoint(IEndpointRouteBuilder routes)
20	    {
21	        routes.MapPost("/invites/{token}/accept",
22	            async (
23	                string token,
24	                HttpContext ctx,
25	                IInvitationService invitationService,
26	                ILoggerFactory loggerFactory,
27	                CancellationToken ct) =>
28	            {
29	                var googleEmail = ctx.User.FindFirst("email")?.Value;
30	                var googleSub = ctx.User.FindFirst("sub")?.Value;
31	                var displayName = ctx.User.FindFirst("name")?.Value ?? googleEmail;
32	
33	                if (string.IsNullOrEmpty(googleEmail) || string.IsNullOrEmpty(googleSub))
34	                    return Results.Unauthorized();
35	
36	                var user = await invitationService.AcceptAsync(
37	                    token, googleEmail, googleSub, displayName!, ct);
