1	using System.Security.Claims;
2	using FluentValidation;
3	using Kanban.Api.Auth;
4	using Microsoft.AspNetCore.Authentication;
5	using Kanban.Business.Interfaces;
6	using Kanban.Business.Transforms;
7	using Kanban.Contracts;
8	using Kanban.Domain.Enums;
9	using Microsoft.AspNetCore.Authentication.Cookies;
10	using Microsoft.AspNetCore.Mvc;
11	using Microsoft.Extensions.Logging;
12	using Microsoft.Extensions.Options;
13	using CorsOptions = Kanban.Api.Options.CorsOptions;
14	
15	namespace Kanban.Api.Endpoints;
16	
17	public static class InviteEndpoints
18	{
19	    public static void MapAcceptEndpoint(IEndpointRouteBuilder routes)
20	    {
21	        routes.MapPost("/invites/{token}/accept",
22	            async (
23	                string token,
24	                HttpContext ctx,
25	                IInvitationService invitationService,
26	                ILoggerFactory loggerFactory,
27	                CancellationToken ct) =>
28	            {
29	                var googleEmail = ctx.User.FindFirst("email")?.Value;
30	                var googleSub = ctx.User.FindFirst("sub")?.Value;
31	                var displayName = ctx.User.FindFirst("name")?.Value ?? googleEmail;
32	
33	                if (string.IsNullOrEmpty(googleEmail) || string.IsNullOrEmpty(googleSub))
34	                    return Results.Unauthorized();
35	
36	                var user = await invitationService.AcceptAsync(
37	                    token, googleEmail, googleSub, displayName!, ct);
38	
39	                // AcceptAsync has committed — user is now a registered Standard user.
40	                // Cookie issuance is best-effort: if it fails the user can sign in via
41	                // the normal flow (/signin → Google → OnTicketReceived recognises them).
42	                try
43	                {
44	                    var identity = new ClaimsIdentity(
45	                        [
46	                            new Claim("sub", googleSub),
47	                            new Claim("email", user.Email),
48	                            new Claim("user_id", user.Id.ToString()),
49	                            new Claim("system_role", "standard"),
50	                        ],
51	                        CookieAuthenticationDefaults.AuthenticationScheme);
52	                    await ctx.SignInAsync(
53	                        CookieAuthenticationDefaults.AuthenticationScheme,
54	                        new ClaimsPrincipal(identity));
55	                }
56	                catch (Exception ex)
57	                {
58	                    loggerFactory
59	                        .CreateLogger(typeof(InviteEndpoints).FullName!)
60	                        .LogWarning(ex,
61	                            "Cookie issuance failed for user {UserId} after acceptance; user can sign in via normal flow",
62	                            user.Id);
63	                }
64	
65	                return Results.Ok(UserTransforms.ToDto(user));
66	            })
67	            .WithName("AcceptInvite")
68	            .WithSummary("Accept an invitation and become a registered user")
69	            .Produces<CurrentUserDto>(200)
70	            .ProducesProblem(410)
71	            .ProducesProblem(422)
72	            .RequireAuthorization()
73	            .RequireRateLimiting("anonymous");
74	    }
75	
76	    public static void Map(IEndpointRouteBuilder routes)
77	    {
78	        routes.MapPost("/invites",
79	            async (
80	                [FromBody] IssueInviteRequest request,
81	                IValidator<IssueInviteRequest> validator,
82	                IInvitationService invitationService,
83	                ICurrentUserService currentUser,
84	                IOptions<CorsOptions> corsOptions,
85	                CancellationToken ct) =>
86	            {
87	                var validationResult = await validator.ValidateAsync(request, ct);
88	                if (!validationResult.IsValid)
89	                {
90	                    var errors = validationResult.Errors
91	                        .GroupBy(e => e.PropertyName.ToLowerInvariant())
92	                        .ToDictionary(g => g.Key, g => g.Select(e => e.ErrorMessage).ToArray());
93	                    return Results.Problem(
94	                        title: "Validation failed.",
95	                        statusCode: StatusCodes.Status422UnprocessableEntity,
96	                        extensions: new Dictionary<string, object?>
97	                        {
98	                            ["code"] = "validation.failed",
99	                            ["errors"] = errors,
100	                        });
101	                }
102	
103	                if (!currentUser.UserId.HasValue)
104	                    return Results.Forbid();
105	
106	                var callerRole = currentUser.SystemRole == "admin"
107	                    ? SystemRole.Admin
108	                    : SystemRole.Standard;
109	
110	                var frontendBaseUrl = corsOptions.Value.AllowedOrigins.FirstOrDefault()
111	                    ?? throw new InvalidOperationException(
112	                        "Cors:AllowedOrigins must contain at least one entry.");
113	
114	                var (response, isNew) = await invitationService.IssueAsync(
115	                    request.Email,
116	                    currentUser.UserId.Value,
117	                    callerRole,
