using Kanban.Api.Auth;
using Kanban.Api.Options;
using Kanban.Business.Interfaces;
using Kanban.Contracts;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Authentication.Google;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Options;
using CorsOptions = Kanban.Api.Options.CorsOptions;

namespace Kanban.Api.Endpoints;

public static class AuthEndpoints
{
    public static void Map(IEndpointRouteBuilder routes)
    {
        var auth = routes.MapGroup("/auth");

        auth.MapGet("/signin",
            ([FromQuery] string? returnUrl, IOptions<CorsOptions> corsOptions) =>
            {
                var frontendBase = corsOptions.Value.AllowedOrigins.FirstOrDefault()
                    ?? "http://localhost:5173";
                var redirectUri = string.IsNullOrWhiteSpace(returnUrl)
                    ? frontendBase
                    : returnUrl.StartsWith('/')
                        ? $"{frontendBase}{returnUrl}"
                        : returnUrl;
                return Results.Challenge(
                    new AuthenticationProperties { RedirectUri = redirectUri },
                    [GoogleDefaults.AuthenticationScheme]);
            })
            .WithName("SignIn")
            .WithSummary("Initiate Google OAuth sign-in")
            .Produces(302)
            .AllowAnonymous()
            .RequireRateLimiting("anonymous");

        auth.MapGet("/me",
            async (ICurrentUserService currentUser, IAuthService authService, CancellationToken ct) =>
            {
                if (!currentUser.IsRegistered || !currentUser.UserId.HasValue)
                    return Results.Forbid();

                var dto = await authService.GetCurrentUserAsync(currentUser.UserId.Value, ct);
                return dto is null ? Results.Forbid() : Results.Ok(dto);
            })
            .WithName("GetCurrentUser")
            .WithSummary("Get the currently authenticated registered user")
            .Produces<CurrentUserDto>(200)
            .ProducesProblem(401)
            .ProducesProblem(403)
            .RequireAuthorization("RegisteredUser");

        auth.MapPost("/signout",
            async (HttpContext ctx) =>
            {
                await ctx.SignOutAsync(CookieAuthenticationDefaults.AuthenticationScheme);
                return Results.NoContent();
            })
            .WithName("SignOut")
            .WithSummary("Sign out the current user")
            .Produces(204)
            .RequireAuthorization();
    }
}

using System.Security.Claims;
using FluentValidation;
using Kanban.Api.Auth;
using Microsoft.AspNetCore.Authentication;
using Kanban.Business.Interfaces;
using Kanban.Business.Transforms;
using Kanban.Contracts;
using Kanban.Domain.Enums;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using CorsOptions = Kanban.Api.Options.CorsOptions;

namespace Kanban.Api.Endpoints;

public static class InviteEndpoints
{
    public static void MapAcceptEndpoint(IEndpointRouteBuilder routes)
    {
        routes.MapPost("/invites/{token}/accept",
            async (
                string token,
                HttpContext ctx,
                IInvitationService invitationService,
                ILoggerFactory loggerFactory,
                CancellationToken ct) =>
            {
                var googleEmail = ctx.User.FindFirst("email")?.Value;
                var googleSub = ctx.User.FindFirst("sub")?.Value;
                var displayName = ctx.User.FindFirst("name")?.Value ?? googleEmail;

                if (string.IsNullOrEmpty(googleEmail) || string.IsNullOrEmpty(googleSub))
                    return Results.Unauthorized();

                var user = await invitationService.AcceptAsync(
                    token, googleEmail, googleSub, displayName!, ct);

                // AcceptAsync has committed — user is now a registered Standard user.
                // Cookie issuance is best-effort: if it fails the user can sign in via
                // the normal flow (/signin → Google → OnTicketReceived recognises them).
                try
                {
                    var identity = new ClaimsIdentity(
                        [
                            new Claim("sub", googleSub),
                            new Claim("email", user.Email),
                            new Claim("user_id", user.Id.ToString()),
                            new Claim("system_role", "standard"),
                        ],
                        CookieAuthenticationDefaults.AuthenticationScheme);
                    await ctx.SignInAsync(
                        CookieAuthenticationDefaults.AuthenticationScheme,
                        new ClaimsPrincipal(identity));
                }
                catch (Exception ex)
                {
                    loggerFactory
                        .CreateLogger(typeof(InviteEndpoints).FullName!)
                        .LogWarning(ex,
                            "Cookie issuance failed for user {UserId} after acceptance; user can sign in via normal flow",
                            user.Id);
                }

                return Results.Ok(UserTransforms.ToDto(user));
            })
            .WithName("AcceptInvite")
            .WithSummary("Accept an invitation and become a registered user")
            .Produces<CurrentUserDto>(200)
            .ProducesProblem(410)
            .ProducesProblem(422)
            .RequireAuthorization()
            .RequireRateLimiting("anonymous");
    }

    public static void Map(IEndpointRouteBuilder routes)
    {
        routes.MapPost("/invites",
            async (
                [FromBody] IssueInviteRequest request,
                IValidator<IssueInviteRequest> validator,
                IInvitationService invitationService,
                ICurrentUserService currentUser,
                IOptions<CorsOptions> corsOptions,
                CancellationToken ct) =>
            {
                var validationResult = await validator.ValidateAsync(request, ct);
                if (!validationResult.IsValid)
                {
                    var errors = validationResult.Errors
                        .GroupBy(e => e.PropertyName.ToLowerInvariant())
                        .ToDictionary(g => g.Key, g => g.Select(e => e.ErrorMessage).ToArray());
                    return Results.Problem(
                        title: "Validation failed.",
                        statusCode: StatusCodes.Status422UnprocessableEntity,
                        extensions: new Dictionary<string, object?>
                        {
                            ["code"] = "validation.failed",
                            ["errors"] = errors,
                        });
                }

                if (!currentUser.UserId.HasValue)
                    return Results.Forbid();

                var callerRole = currentUser.SystemRole == "admin"
                    ? SystemRole.Admin
                    : SystemRole.Standard;

                var frontendBaseUrl = corsOptions.Value.AllowedOrigins.FirstOrDefault()
                    ?? throw new InvalidOperationException(
                        "Cors:AllowedOrigins must contain at least one entry.");

                var (response, isNew) = await invitationService.IssueAsync(
                    request.Email,
                    currentUser.UserId.Value,
                    callerRole,
                    frontendBaseUrl,
                    ct);

                return isNew
                    ? Results.Created((string?)null, response)
                    : Results.Ok(response);
            })
            .WithName("IssueInvite")
            .WithSummary("Issue an invitation to a new user")
            .Produces<IssueInviteResponse>(201)
            .Produces<IssueInviteResponse>(200)
            .ProducesProblem(422)
            .ProducesProblem(409)
            .ProducesProblem(403)
            .RequireAuthorization("Admin")
            .RequireRateLimiting("mutating");
    }
}

